const err = $input.first().json;
const rawMessage = (err.execution && err.execution.error && err.execution.error.message) || 'Unknown error';
const failingNode = (err.execution && err.execution.error && err.execution.error.node && err.execution.error.node.name) || 'Unknown node';
const runId = (err.execution && err.execution.id) || 'unknown';
const workflowName = (err.workflow && err.workflow.name) || 'unknown';
const executionUrl = (err.execution && err.execution.url) || '';

let errorMessage = rawMessage;

if (failingNode === 'Convert HTML to PDF (PDFShift API)' && /invalid credential/i.test(rawMessage)) {
  errorMessage = 'The PDF engine is set to "api" (PDFShift) but its credential is not configured in n8n. Add a Header Auth credential (Header Name: X-API-Key, Header Value: your PDFShift key) to the "Convert HTML to PDF (PDFShift API)" node, or set Config.pdfEngine back to "gotenberg" to use the self-hosted engine instead. (Original n8n error: ' + rawMessage + ')';
}

return [{
  json: {
    runId: runId,
    workflowName: workflowName,
    failingNode: failingNode,
    errorMessage: errorMessage,
    executionUrl: executionUrl,
  },
}];
